// 参考解答：连续整数全排列（DFS + 回溯）
// 按字典序输出 m, m+1, ..., m+n-1 这 n 个整数的所有全排列。
// 递归到位置 pos 时，从小到大尝试每个未用过的数字，递归返回后恢复现场（回溯），
// 由于候选值按升序尝试，输出天然为字典序。
#include <iostream>
using namespace std;

int m, n;
int perm[8];
bool used[8];

void dfs(int pos) {
    if (pos == n) {
        for (int i = 0; i < n; i++) {
            if (i > 0) cout << " ";
            cout << perm[i];
        }
        cout << "\n";
        return;
    }
    for (int v = 0; v < n; v++) {          // v 是候选下标：数值为 m + v
        if (!used[v]) {
            used[v] = true;
            perm[pos] = m + v;
            dfs(pos + 1);
            used[v] = false;               // 回溯：恢复现场，尝试下一个候选
        }
    }
}

int main() {
    cin >> m >> n;
    dfs(0);
    return 0;
}

// 参考解答：活动选择（贪心）
// 按"结束时间升序（结束相同按开始升序）"排序后，依次选择与已选活动不冲突
// （开始时间 >= 最后选中活动的结束时间）的活动。最早结束贪心可保证选出数量最多。
#include <iostream>
#include <algorithm>
using namespace std;

struct Activity { int s, e; };

bool cmp(const Activity& a, const Activity& b) {
    if (a.e != b.e) return a.e < b.e;
    return a.s < b.s;
}

int main() {
    int n;
    cin >> n;
    Activity act[1005];
    for (int i = 0; i < n; i++) cin >> act[i].s >> act[i].e;
    sort(act, act + n, cmp);
    int lastEnd = -1;              // 开始时间 >= 0，首个活动必被选中
    int cnt = 0;
    Activity chosen[1005];
    for (int i = 0; i < n; i++) {
        if (act[i].s >= lastEnd) {  // 端点相接（开始 == 上一个结束）不算冲突
            chosen[cnt++] = act[i];
            lastEnd = act[i].e;
        }
    }
    cout << cnt << "\n";
    for (int i = 0; i < cnt; i++) cout << chosen[i].s << " " << chosen[i].e << "\n";
    return 0;
}
